# 10_all_sites.R: all-site coherent fits of spread-only MS-GDM and additive MS-GDUM (identical 6,000 training combinations, seed 7000 + k), matched-profile predictions, contrasts and independent marginal fits.
# Contrast A: TP spread s1 -> s2 at fixed TP position (10, 35, 100 ug/L), TN, Chl-a, geography and the internal arrangement of each reference profile preserved.
# Contrast B: TP position Low -> Intermediate -> High at fixed TP spread (additive: decomposition into spline-slope and explicit-position terms). Matched interval: common to both orders of a taxon (and to both pools when available); unavailable panels are NOT forced.
# Usage (final/, ZG_LIB6 = principal package library): Rscript revision_fig6/10_all_sites.R
source("revision_fig6/00_fig6_common.R"); T0 <- Sys.time(); OUT <- "revision_fig6/tables"; dir.create(file.path(OUT, "support"), FALSE, TRUE); assign("OUT", file.path(OUT, "support"), envir = globalenv())
PREP <- list(); for (pool in POOLSET) for (tx in names(ORD)) for (k in ORD[[tx]]) { PREP[[paste(pool, tx, k)]] <- prepare(pool, tx, k, get_d(pool, tx)); message("prepared ", pool, " ", tx, " k", k) }
OUT <- "revision_fig6/tables"
# ---- matched interval per taxon (same rule as the earlier Figure 6): common to both orders; prefer also both pools
SEL <- list(); for (tx in names(ORD)) { k2 <- ORD[[tx]][1]; kh <- ORD[[tx]][2]; low <- PREP[[paste("shared", tx, k2)]]; high <- PREP[[paste("shared", tx, kh)]]; kk <- intersect(names(low$valid), names(high$valid)); both <- Reduce(intersect, list(kk, names(PREP[[paste("full", tx, k2)]]$valid), names(PREP[[paste("full", tx, kh)]]$valid)))
  iv <- best_interval(if (length(both)) both else kk); SEL[[tx]] <- list(interval = iv, rule = if (length(both)) "common to both orders and both pools" else if (!is.na(iv)) "common to both shared-pool orders" else "no common interval") }
SUP <- list(); for (pool in POOLSET) for (tx in names(ORD)) for (k in ORD[[tx]]) { p <- PREP[[paste(pool, tx, k)]]; iv <- SEL[[tx]]$interval; ok <- !is.na(iv) && iv %in% names(p$valid); ij <- if (!is.na(iv)) parse_iv(iv) else c(NA, NA)
  SUP[[length(SUP) + 1]] <- data.frame(pool = pool, group = tx, taxon = TXL[[tx]], order = k, n_valid_common_intervals = length(p$valid), matched_interval = iv, interval_rule = SEL[[tx]]$rule, matched_available = ok, spread_from = if (ok) GRID[ij[1]] else NA, spread_to = if (ok) GRID[ij[2]] else NA, n_supported_reference_configurations = if (ok) length(p$valid[[iv]]) else 0L, nn_threshold = p$threshold,
    max_common_profiles_any_spread = max(colSums(p$ok)), n_training_sets = nrow(p$dd$idx), n_unique_training_sets = sum(!duplicated(t(apply(p$dd$idx, 1, sort))))) }
SUP <- bind_rows(SUP); write.csv(SUP, file.path(OUT, "fig6_support_summary.csv"), row.names = FALSE); print(as.data.frame(SUP[, c("pool", "group", "order", "matched_interval", "matched_available", "n_supported_reference_configurations")]))
# ---- fits, grid predictions, contrasts
GR <- list(); PRED <- list(); CA <- list(); CB <- list(); LINK <- list(); MARG <- list(); POSC <- list(); FITINFO <- list()
for (r in seq_len(nrow(SUP))) { s <- SUP[r, ]; if (!s$matched_available) next; pool <- s$pool; tx <- s$group; k <- s$order; p <- PREP[[paste(pool, tx, k)]]; d <- get_d(pool, tx); iv <- parse_iv(s$matched_interval); sp_idx <- iv[1]:iv[2]; svals <- GRID[sp_idx]; ids <- select_ids(p$valid[[s$matched_interval]]); y <- ugdm_component_response(d$x, p$dd$idx)
  dd <- list(additive = p$dd, spread_only = ugdm_component_design(p$E, p$dd$idx, "spread_only", coordinates = p$xy, lonlat = TRUE)); fits <- lapply(dd, function(z) ugdm_fit_components(z, y, "coherent")); ind <- lapply(dd, function(z) ugdm_fit_components(z, y, "independent"))
  FITINFO[[length(FITINFO) + 1]] <- do.call(rbind, lapply(names(fits), function(m) data.frame(pool = pool, group = tx, order = k, model = m, converged = fits[[m]]$converged, share_identified = fits[[m]]$share_identified, n_parameters_total = length(fits[[m]]$fits$total$coef), D2_in_sample_total = 1 - fits[[m]]$fits$total$deviance / fits[[m]]$fits$total$null_deviance)))
  G <- list(); for (m in names(fits)) { bT <- setNames(bvec(fits[[m]], "total"), colnames(layoutfn(dd[[m]], TRUE)$X)); bS <- setNames(bvec(fits[[m]], "share"), names(bT)); for (pn in names(PCOL)) for (sv in svals) G[[paste(m, pn, sv)]] <- cell_parts(p, dd[[m]], m, ids, log10(PCOL[[pn]]), sv, bT, bS) }
  s_lo <- svals[1]; s_hi <- svals[length(svals)]; s_mid <- svals[ceiling(length(svals) / 2)]
  for (m in names(fits)) { for (pn in names(PCOL)) { for (sv in svals) { a <- G[[paste(m, pn, sv)]]; rr <- resp_from(a$oT + a$sT + a$pT, a$oS + a$sS + a$pS); PRED[[length(PRED) + 1]] <- data.frame(pool = pool, group = tx, order = k, model = m, position = pn, TP_ugL = PCOL[[pn]], spread = sv, n_profiles = nrow(a), total = mean(rr$total), occupancy = mean(rr$occupancy), heterogeneity = mean(rr$heterogeneity), eta_total = mean(a$oT + a$sT + a$pT), eta_share = mean(a$oS + a$sS + a$pS), sp_terms_total = mean(a$sT), pos_terms_total = mean(a$pT), other_terms_total = mean(a$oT), sp_terms_share = mean(a$sS), pos_terms_share = mean(a$pS)) }
        ca <- contrast_A(G, m, pn, s_lo, s_hi); CA[[length(CA) + 1]] <- cbind(pool = pool, group = tx, order = k, ca, comp_measures(ca$dT_pp, ca$dO_pp, ca$dH_pp)) }
    for (sv in unique(c(s_lo, s_mid, s_hi))) for (pr in list(c("Low", "Intermediate"), c("Intermediate", "High"), c("Low", "High"))) CB[[length(CB) + 1]] <- cbind(pool = pool, group = tx, order = k, contrast_B(G, m, pr[1], pr[2], sv)) }
  # independent marginal fits (Version B): spread transformation f(TP) and explicit position contribution g(TP) per component, link scale
  zg <- seq(log10(10), log10(100), length.out = 1); dom <- quantile(p$E$TP, c(.02, .98), names = FALSE); zgrid <- seq(dom[1], dom[2], length.out = 60)
  for (m in names(ind)) { f <- ind[[m]]; tb <- dd[[m]]$basis; ctr <- tb$center[["TP"]]; scl <- tb$scale[["TP"]]; spl <- tb$splines[[match("TP", dd[[m]]$vars)]]; bnd <- attr(spl, "Boundary.knots"); Bz <- function(z) unclass(predict(spl, pmin(pmax((z - ctr) / scl, bnd[1]), bnd[2])))[, 1:3, drop = FALSE]; cn <- colnames(layoutfn(dd[[m]], TRUE)$X)
    for (st in names(f$fits)) { b <- setNames(drop(f$transform %*% f$fits[[st]]$coef), cn); sp <- b[paste0("TP_f", 1:3)]; fz <- drop(Bz(zgrid) %*% sp); MARG[[length(MARG) + 1]] <- data.frame(pool = pool, group = tx, order = k, model = m, component = st, TP_log10 = zgrid, TP_ugL = 10^zgrid, f = fz, f_centred = fz - fz[1], converged = isTRUE(f$fits[[st]]$converged), beta1 = sp[[1]], beta2 = sp[[2]], beta3 = sp[[3]])
      if (m == "additive") { bnull <- b; ps <- cell_parts(p, dd[[m]], m, ids[seq_len(min(60, length(ids)))], zgrid[1], 0, b, b); gv <- vapply(zgrid, function(zz) { q <- cell_parts(p, dd[[m]], m, ids[seq_len(min(60, length(ids)))], zz, 0, b, b); mean(q$pT) }, 0); POSC[[length(POSC) + 1]] <- data.frame(pool = pool, group = tx, order = k, component = st, TP_log10 = zgrid, TP_ugL = 10^zgrid, g = gv, g_centred = gv - gv[1]) } } }
  message("done ", pool, " ", tx, " k", k, " ", format(Sys.time() - T0)) }
w <- function(l, f) write.csv(bind_rows(l), file.path(OUT, f), row.names = FALSE); w(PRED, "fig6_predictions_grid.csv"); w(CA, "fig6_contrast_A_spread.csv"); w(CB, "fig6_contrast_B_position.csv"); w(MARG, "fig6_independent_spread_curves.csv"); w(POSC, "fig6_independent_position_contributions.csv"); w(FITINFO, "fig6_fit_info.csv")
cat("finished", format(Sys.time() - T0), "\n")
